        title: ruBlock.title, desc: ruBlock.desc, cta: ruBlock.cta,
        format: def.ideaFormat, status: 'ready', source: 'manual',
        targetGroups: draft.productId ? [draft.productId] : [],
        coverAssetId: draft.selectedCoverAssetId || null,
