/* ============================================================
   СОЗДАНИЕ КОНТЕНТА (.cc-*)
   Своё пространство имён вместо инлайновых стилей в шаблонах
   renderContentDraftCard() / renderAgentContentDrafts() (app.js):
   активное состояние вкладок и чипов раньше задавалось строками
   вида style="background:var(--accent-blue)" прямо в разметке.
   ============================================================ */

.cc-toprow { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 18px; }

/* Пайплайн страницы: раньше это был абзац "Тема → 4 формата → перевод → хранилище". */
.cc-flow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cc-flow-step { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; color: var(--text-secondary); }
.cc-flow-step b { display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; border-radius: 50%; background: rgba(255,255,255,0.08); font-size: 10px; color: var(--text-primary); }
.cc-flow-arrow { color: var(--text-secondary); opacity: 0.45; font-size: 12px; }

/* КАРТОЧКА ЧЕРНОВИКА */
.cc-card { background: var(--bg-grouped); border: 1px solid rgba(255,255,255,0.06); border-radius: 16px; margin-bottom: 14px; overflow: hidden; }
.cc-card.collapsed { background: rgba(28,28,30,0.6); }

.cc-head { display: flex; align-items: flex-start; gap: 12px; padding: 14px 16px; }
.cc-collapse { flex-shrink: 0; width: 26px; height: 26px; border: none; border-radius: 8px; background: rgba(255,255,255,0.06); color: var(--text-secondary); font-size: 12px; cursor: pointer; }
.cc-collapse:hover { background: rgba(255,255,255,0.12); color: var(--text-primary); }
.cc-head-main { flex: 1; min-width: 0; }
.cc-head-title { font-size: 15px; font-weight: 600; line-height: 1.35; overflow-wrap: anywhere; }
.cc-head-meta { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 7px; }
.cc-muted { color: var(--text-secondary); font-weight: 400; }

.cc-pill { display: inline-flex; align-items: center; font-size: 11px; font-weight: 600; padding: 3px 9px; border-radius: 7px; background: rgba(255,255,255,0.07); color: var(--text-secondary); }
.cc-pill-work { background: rgba(255,159,10,0.15); color: var(--accent-orange); }
.cc-pill-ready { background: rgba(10,132,255,0.15); color: var(--accent-blue); }
.cc-pill-done { background: rgba(48,209,88,0.15); color: var(--accent-green); }
